  if(d.ref){const ref=packet.policy_packet.owner_registry.find(p=>p.research_key===d.ref);const nr=packet.records.find(p=>p.slot_id===d.ref);technology_reference={status:'matched',research_key:ref.research_key,product_id:null,formula_sha256:ref.normalized_sha256,source_version:ref.source_version,shared_markers:d.markers,source_ids:uniq([...d.formula,...nr.formula_source_ids]),limitation:'Exact frozen chemistry reference only. Reference identity, owner tier, efficacy, formulation conditions, fit and instructions do not transfer; the normalized formula digest is copied from the supplied reference tuple.'};}
  const evidence={supported_outcome:d.outcome,summary:d.summary,detail:d.detail,scientific:{supporting_source_ids:d.sciSupport,counter_source_ids:d.sciCounter,limitations:uniq([...d.limits,'Abstracts, supplier materials, patent examples and their amendments are not upgraded to independent finished-product trials. Duplicate papers/amendments are not independent studies.'])},practical:{supporting_source_ids:d.practicalSupport,counter_source_ids:d.practicalCounter,limitations:['Practical/creator evidence is uncontrolled and separate from scientific evidence.',...(d.practicalSupport.length||d.practicalCounter.length?['Source affiliation, historical formula and routine confounding remain visible.']:['No inspected original product-specific practical verdict is available in the frozen packet; missing evidence is neutral.'])]},applicability:d.bridges.map(([scope,source_ids,bridge])=>({scope,source_ids,bridge,limitations:['Applicability is bounded by the source registry; no hidden formulation, pack or protocol equivalence is assumed.']})),manufacturer_positioning:d.positioning,cautions:d.limits};
  let trace=[`Stage A candidates: ${prior.candidate_families.join(', ')||'none'}.`,d.boundaryWhy];
  if(prior.candidate_families.includes('acid_calcium_management')&&d.family!=='acid_calcium_management') trace.push('Citric Acid remains a literal observation but no targeted acid/calcium use is established for this identity; that candidate is not promoted to a final acid family.');
  if(d.family==='acid_calcium_management')trace.push('Named targeted acid/bonding or decalcifying use provides the category bridge; formula acid presence alone was insufficient.');
  trace.push(d.boundary==='in_scope'?`Final family ${d.family}; ${owner?'exact owner entry':'owner default'} policy applied separately from scientific certainty.`:`Final ${d.boundary}; family, trust tier and basis remain null.`);
  const conflicts=(named.formula_conflicts??[]).map(c=>`${c.resolved?'Resolved':'Unresolved'} formula capture (${c.source_ids.join(', ')}): ${c.reason}`);
  conflicts.push(...(named.conflicts??[]));
  if(id==='P01')conflicts.push('R05 explicitly reports a global/local formula difference; full alternate raw formula is not supplied here and is not reconstructed.');
  if(id==='P04')conflicts.push('R01 current 22% complex and R08 older 12% copy differ; complex percentages are not ingredient dose and older wording is not selected.');
